    "content": "Kültürel miras kavramı ve önemi hakkında bilgi sahibi olma",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi ve akademik tartışma.",
    "resources": "Kaynaklar: Öcal, O. (2007). UNSECO, Kültür ve Türkiye. Milli Folklor, 73, 5-11 Öcal, O. (2009). Somut olmayan kültürel miras nedir? Ankara: Geleneksel Yayıncılık Deniz, T. Ve Diker, O. (2017). Coğrafya Ve Tarih Perspektifinden Somut Kültürel Miras Ve Türkiye, Ankara: Pegem Akademi Ahunbay, Z. (2009). \"Tarihi Çevre Koruma ve Restorasyon\". YEM",
