    "prerequisites": "Yok",
    "instructor": "Yok",
    "purpose": "Lisansüstü öğrencisine “Pazarlama\" konusunda genel bir bakış açısı geliştirmelerineolanak vermek, pazarlamanın değişik fonksiyonlarını anlamalarını sağlamak, bu değişikfonksiyonların nasıl yürütüldüğünü ve bu farklı fonksiyonların birbirini nasıl etkilediğinigöstermektir. Bununla birlikte, ekoturizmde pazarlama kavramı, özellikleri ve işleyişineilişkin konular ele alınacaktır.",
    "content": "Pazarlamada Temel Kavramlar, Pazarlama Çevresi ve Pazar Fırsatlarının Analizi, TuristDavranışlarının Analizi, Pazarlama Bilgi Sistemi ve Pazarlama Araştırması, EkoturizmKavramı, Pazar Bölümlendirme, Ekoturizmde Hedef Pazar Seçimi ve Konumlandırma,Pazarlama Karması ve Ekoturizm Pazarlama Kararları, Ekoturizm Pazarlama Stratejilerikonuları ele alınacaktır.",
    "methods": "Yüz yüze",
    "resources": "Kaynaklar: Fennell, D.A. (2002). Ecotourism: An Introduction. Routledge.; Ders Notları: Özgen Çiğdemli, A.Ö. (2021). Ekoturizmi Anlamak, Detay Yayıncılık: Ankara. Belber, G. B. Ekoturizmde Pazarlama Çabaları ve TuristDavranışları, Detay Yayıncılık",
