    "purpose": "Öğrencilerin korunan/doğal alanlarda ekoturizm planlamasını kuramsal ve etik temelde yapabilmesi; taşıma kapasitesi ve sezonsallık/fiyatlama ile ziyaretçi yönetimini kurgulayabilmesi; paydaş katılımı ve yerel değer zinciri perspektifiyle sürdürülebilir ürün/rota geliştirebilmesi.",
    "content": "Ekoturizm ve sürdürülebilirlik kuramları; IUCN ve ulusal koruma statüleri; biyoçeşitlilik–turizm etkileşimi; taşıma kapasitesi ve sezonsallık/fiyatlama; paydaş analizi ve katılımcı yönetişim; yerel kalkınma ve değer zinciri; sürdürülebilir deneyim/ürün/rota tasarımı; etik ve eko-etiketler; ziyaretçi iletişimi ve memnuniyet ölçümü; Türkiye ve dünyadan vaka çalışmaları.",
    "methods": "Düz Anlatım, Soru-Cevap, Tartışma, Beyin Fırtınası",
    "resources": "Kaynaklar: Özgen Çiğdemli, A.Ö. (2019).Ekoturizmi Anlamak, Detay Yayıncılık; Ders Notları: Konu ile ilgili makaleleri ve kitapları inceleme",
