    "content": "Organik hayvancılığın yaygınlaştırılması; doğanın ve eko sistemin korunmasına, küçük çiftçilerin gelir düzeyinin artmasına, köyden kente göçün önlenmesine, başta genç nesil olmak üzere insanlar için daha sağlıklı ve fonksiyonel ürünler üretilmesine ve daha sağlıklı beslenmelerine olanak sağlayacak mühendisler yetiştirmek.",
    "methods": "Organik hayvancılığın yaygınlaştırılması; doğanın ve eko sistemin korunmasına, küçük çiftçilerin gelir düzeyinin artmasına, köyden kente göçün önlenmesine, başta genç nesil olmak üzere insanlar için daha sağlıklı ve fonksiyonel ürünler üretilmesine ve daha sağlıklı beslenmelerine olanak sağlayacak mühendisler yetiştirmek.",
