    "purpose": "İnsanlık tarihinin en köklü dönüşümü olan tarımsal devrimden günümüzün modern biyoteknolojik uygulamalarına kadar geçen süreci; sosyal, ekonomik ve bilimsel boyutlarıyla incelemektir.",
    "content": "Ders; avcı-toplayıcılıktan yerleşik hayata geçiş, ilk çağ uygarlıklarının tarım yöntemleri, Orta Çağ feodal yapısı ve İslam dünyasındaki tarımsal gelişmeler, Osmanlı toprak düzeni, Rönesans ve Sanayi Devrimi sonrası mekanizasyon, Yeşil Devrim süreci ve modern tarım biyoteknolojisi konularını kapsamaktadır.",
