      "Organik tarımın esasları ve uygulanmasına ilişkin yönetmelik-4 Kontrol ve sertifikasyon sisteminin işleyişi",
      "Organik tarımın esasları ve uygulanmasına ilişkin yönetmelik-5 ((organik tarımda sulama,Hasat ve depolama esasları)",
      "Organik tarımda ekim nöbetinin önemi, ekim nöbeti uygulamaları",
      "Organik tarımda yabancı ot ve kontrolü",
