    "purpose": "Sanat Tarihi disiplini içerisinde kullanılan bütün tanım ve terminolojisinin görselle desteklenerek öğrenciye Sanat Tarihi alanında temel oluşturmak.",
    "content": "Bu derste, sanatın ortaya çıkışına ilişkin kuramlar, sanatın toplumsal tarihine ilişkin bilgiler, modernizm ve bunun getirdiği modern sanat kuramları, sanat tarihinde ikonografik ve ikonolojik çözümlemeler ele alınmaktadır.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi ve akademik tartışma.",
    "resources": "Kaynaklar: C. E. ARSEVEN, Sanat Ansiklopedisi, İstanbul, 1983; D. HASOL, Ansiklopedik Mimarlık Sözlüğü, İstanbul, 1979; Ders Notları: Haldun Özkan, Sanat Tarihine Giriş Ders Notları, Erzurum, 2017.",
    "sdgs": [
      "4",
      "11",
      "12"
    ],
    "outcomes": [
      "Sanat tarihi ve kültürel değerler kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Kültürel miras ve yorumlama alanındaki uygulamaları karşılaştırır.",
      "Sanat tarihi ve kültürel değerler için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Sanat tarihi ve kültürel değerler faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Sanat tarihi ve kültürel değerler bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Sanat tarihi terminolojisi",
      "Mimari terminoloji",
      "Yapı gereçleri terminolojisi, taş ve tuğla duvar örgü çeşitleri",
      "Mimari taşıyıcılar( duvar, paye, sütun, sütunce) ve terminolojisi",
      "Tonoz ve kemer inşası",
      "Tonoz ve kemer çeşitleri",
      "Kubbe inşası ve çeşitleri",
      "Cami terminolojisi, bölümleri ve plan türleri",
      "Minare yapımı ve terminolojisi",
      "Taç kapılar ve terminolojisi",
      "Medreseler, plan türleri ve terminolojisi",
      "Anıt Mezarlar plan türleri ve terminolojisi",
      "Kervansaraylar, plan türleri ve terminolojisi",
      "Sanat tarihi ve kültürel değerler: kapsam ve temel kavramlar",
      "Somut ve somut olmayan miras"
    ],
